const select=(key,label,values)=>[key,label,'select',values];
export const governanceSchemas={
 compliance:{label:'EIR compliance matrix',columns:[['id','Requirement ID'],['source','Source / revision / clause'],['requirement','Requirement'],['section','BEP section ID'],['owner','Owner'],['evidence','Evidence / reference'],select('status','Compliance',['Open','Compliant','Deviation accepted','Not applicable']),['justification','Deviation / exclusion justification'],['authority','Decision authority']]},
 detailedResponsibilities:{label:'Detailed responsibility matrix',columns:[['id','Package ID'],['scope','Model / system / package'],['milestone','Milestone'],['inputs','Inputs / dependencies'],['producer','Producer'],['reviewer','Technical reviewer'],['authorizer','Authorizer'],['receiver','Receiver'],['boundary','Scope boundary / interface']]},
 mobilization:{label:'Mobilization and capability',columns:[['id','Activity ID'],['activity','Activity / capability test'],['owner','Owner'],['resources','People / capacity / tools'],['date','Target date','date'],select('status','Status',['Planned','In progress','Passed','Failed','Not applicable']),['evidence','Test / training evidence'],['checker','Checker / exclusion authority']]},
 risks:{label:'Information delivery risks',columns:[['id','Project risk ID'],['risk','Risk / cause / impact'],['owner','Owner'],select('likelihood','Likelihood',['Low','Medium','High']),select('impact','Impact',['Low','Medium','High']),['mitigation','Mitigation / response'],['date','Action due','date'],select('status','Status',['Open','Mitigating','Accepted','Closed']),['evidence','Acceptance / closure evidence']]},
 approvals:{label:'BEP review and authorization records',columns:[select('stage','Stage',['Technical review','Issue authorization','Client acceptance']),['revision','BEP revision'],['person','Reviewer / approver'],['role','Role / organization'],select('status','Decision',['Pending','Approved','Rejected']),['date','Decision date','date'],['evidence','Approval record / transmittal'],['contentKey','Content reference','readonly']]},
 changeLog:{label:'BEP change register',columns:[['revision','Revision'],['date','Change date','date'],['sections','Affected sections'],['reason','Change / reason'],['author','Author'],['reference','Instruction / decision reference']]}
};
export const deliveryColumns=[['id','Deliverable ID'],['tidp','Task team / TIDP'],['title','Deliverable'],['packageId','Responsibility package ID'],['milestone','Milestone'],['producer','Producer'],['reviewer','Reviewer'],['dependencies','Predecessor IDs (comma separated)'],['productionDays','Production days','number'],['reviewDays','Review days','number'],['date','Date','date'],['forecastDate','Forecast issue','date'],['actualDate','Actual issue','date'],['revision','Revision'],select('status','Status',['Planned','In progress','Submitted','Accepted','Rejected']),['format','Format'],['acceptance','Acceptance'],['evidence','Acceptance evidence']];
export const unresolved=value=>!String(value||'').trim()||/\[[^\]]+\]|\b(?:TBC|TBD|pending confirmation|to be (?:agreed|confirmed)|approval pending|named .* at (?:mobilization|issue)|project-approved version)\b/i.test(String(value));
export const validDate=value=>/^\d{4}-\d{2}-\d{2}$/.test(value||'')&&!Number.isNaN(Date.parse(value))&&new Date(value).toISOString().slice(0,10)===value;
const stable=value=>Array.isArray(value)?value.map(stable):value&&typeof value==='object'?Object.fromEntries(Object.keys(value).sort().map(k=>[k,stable(value[k])])):value;
// Exact serialized content comparison is retained locally on approval rows. No cryptographic-signature claim.
export function approvalContent(p){return JSON.stringify(stable({fields:p.fields,lists:Object.fromEntries(Object.entries(p.lists).filter(([key])=>key!=='approvals')),notes:p.notes,moduleStates:p.moduleStates,style:p.style,attachments:p.attachments||[]}));}
export function contentKey(p){const s=approvalContent(p);let h=2166136261;for(let i=0;i<s.length;i++)h=Math.imul(h^s.charCodeAt(i),16777619);return `BEP-${(h>>>0).toString(16).padStart(8,'0')}`;}
export function bindApproval(p,index){const row=p.lists.approvals[index];if(!row)throw new Error('Approval record not found.');row.contentKey=contentKey(p);row.contentSnapshot=approvalContent(p);}
export function approvalValid(p,row){return row.status==='Approved'&&row.revision===p.fields.revision&&validDate(row.date)&&!unresolved(row.person)&&!unresolved(row.role)&&!unresolved(row.evidence)&&row.contentSnapshot===approvalContent(p);}
export function deliverySummary(rows,today=new Date().toISOString().slice(0,10)){return {total:rows.length,issued:rows.filter(r=>validDate(r.actualDate)).length,onTime:rows.filter(r=>validDate(r.actualDate)&&validDate(r.date)&&r.actualDate<=r.date).length,overdue:rows.filter(r=>validDate(r.date)&&!validDate(r.actualDate)&&r.date<today).length,accepted:rows.filter(r=>r.status==='Accepted'&&validDate(r.actualDate)&&!unresolved(r.evidence)).length};}
export function governanceIssues(p){const issues=[],add=(key,i,message)=>issues.push({severity:'critical',code:i===null?key:`row:${key}:${i}`,message});
 const needed={compliance:['id','source','requirement','section','owner'],detailedResponsibilities:['id','scope','milestone','producer','reviewer','authorizer','receiver','boundary'],mobilization:['id','activity','owner','resources'],risks:['id','risk','owner','mitigation'],deliverables:['id','tidp','title','packageId','milestone','producer','reviewer','revision','format','acceptance']};
 for(const [key,fields] of Object.entries(needed)){const rows=p.lists[key]||[];if(!rows.length&&key!=='risks')add(key,null,`Complete ${key} before issue.`);const ids=new Set();rows.forEach((r,i)=>{const missing=fields.filter(f=>unresolved(r[f]));if(missing.length)add(key,i,`${key} row ${i+1}: complete ${missing.join(', ')}.`);if(r.id&&ids.has(r.id))add(key,i,`Duplicate identifier: ${r.id}.`);ids.add(r.id);});}
 (p.lists.compliance||[]).forEach((r,i)=>{if(!Object.hasOwn(p.moduleStates,r.section))add('compliance',i,'Map requirement to a valid BEP section ID.');if(!['Compliant','Deviation accepted','Not applicable'].includes(r.status)||unresolved(r.evidence))add('compliance',i,'Resolve requirement and record supporting evidence.');if(r.status!=='Compliant'&&(unresolved(r.justification)||unresolved(r.authority)))add('compliance',i,'Record exclusion/deviation justification and authority.');});
 (p.lists.mobilization||[]).forEach((r,i)=>{if(!['Passed','Not applicable'].includes(r.status)||unresolved(r.evidence)||unresolved(r.checker))add('mobilization',i,'Complete mobilization test or record authorized exclusion, with evidence and checker.');if(!validDate(r.date))add('mobilization',i,'Set a valid mobilization target date.');});
 (p.lists.risks||[]).forEach((r,i)=>{if(!validDate(r.date))add('risks',i,'Set a valid risk action date.');if(['Accepted','Closed'].includes(r.status)&&unresolved(r.evidence))add('risks',i,'Record risk acceptance / closure evidence.');if(r.impact==='High'&&['Open','Mitigating'].includes(r.status))add('risks',i,'High-impact information risk requires disposition before issue.');});
 const rows=p.lists.deliverables||[],byId=new Map(rows.map(r=>[r.id,r]));
 const dependencies=r=>String(r.dependencies||'').split(',').map(s=>s.trim()).filter(Boolean);
 rows.forEach((r,i)=>{if(!validDate(r.date))add('deliverables',i,'Set the baseline planned issue date.');for(const k of ['forecastDate','actualDate'])if(r[k]&&!validDate(r[k]))add('deliverables',i,`Invalid ${k}.`);for(const k of ['productionDays','reviewDays'])if(r[k]===''||r[k]===undefined||!Number.isInteger(Number(r[k]))||Number(r[k])<0)add('deliverables',i,`Set non-negative whole ${k}.`);if(!(p.lists.detailedResponsibilities||[]).some(x=>x.id===r.packageId))add('deliverables',i,'Link a valid responsibility package ID.');for(const id of dependencies(r))if(!byId.has(id)||id===r.id)add('deliverables',i,`Invalid predecessor: ${id}.`);const seen=new Set();const cyclic=id=>{if(id===r.id)return true;if(seen.has(id)||!byId.has(id))return false;seen.add(id);return dependencies(byId.get(id)).some(cyclic);};if(dependencies(r).some(cyclic))add('deliverables',i,'Circular delivery dependencies.');if(['Submitted','Accepted','Rejected'].includes(r.status)&&!validDate(r.actualDate))add('deliverables',i,'Issued deliverable requires an actual issue date.');if(r.status==='Accepted'&&unresolved(r.evidence))add('deliverables',i,'Accepted deliverable requires acceptance evidence.');});
 return issues;
}
export function seedGovernance(p){
 p.lists.compliance=[{id:'REQ-001',source:'[Client EIR revision / clause]',requirement:'Confirm project naming, exchanges and information acceptance criteria against the received EIR.',section:'references',owner:'HATCO BIM Manager',evidence:'',status:'Open',justification:'',authority:''}];
 p.lists.detailedResponsibilities=[{id:'PKG-BIM',scope:'HATCO BIM delivery and appointed discipline coordination',milestone:'Construction',inputs:'Approved design references and project EIR',producer:'HATCO discipline task teams',reviewer:'HATCO Discipline Lead',authorizer:'HATCO Project Manager',receiver:'Designated project reviewer',boundary:'HATCO appointed scope; external leadership per appointment'}];
 p.lists.mobilization=['Confirm team capability and available capacity','Configure accounts, permissions and worksharing','Test coordinates and native / NWC / IFC exchange','Train team on HATCO standards and issue workflow','Test backup restoration'].map((activity,i)=>({id:`MOB-${i+1}`,activity,owner:'HATCO BIM Manager',resources:'[Assigned people / tools / availability]',date:'',status:'Planned',evidence:'',checker:''}));
 p.lists.risks=[{id:'R-BIM-001',risk:'Missing EIR or survey reference may cause rework and rejected exchanges.',owner:'HATCO BIM Manager',likelihood:'Medium',impact:'High',mitigation:'Obtain and verify requirements and survey before affected production; link to project risk register.',date:'',status:'Open',evidence:''}];
 p.lists.changeLog=[{revision:p.fields.revision,date:p.fields.issueDate,sections:'All',reason:'Initial company baseline adapted to project; review required.',author:'HATCO BIM function',reference:'HAT-BIM-STD-001'}];
 p.lists.approvals=['Technical review','Issue authorization'].map(stage=>({stage,revision:p.fields.revision,person:'',role:'',status:'Pending',date:'',evidence:'',contentKey:''}));
 p.lists.deliverables=p.lists.deliverables.map((r,i)=>({...r,id:`DEL-${String(i+1).padStart(3,'0')}`,tidp:'HATCO',packageId:'PKG-BIM',milestone:i===p.lists.deliverables.length-1?'Handover':'Construction',reviewer:'HATCO Discipline Lead',dependencies:'',productionDays:'',reviewDays:'',forecastDate:'',actualDate:'',revision:'P01',status:'Planned',evidence:''}));
 return p;
}
